package com.bankgroups;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Not a real unit test - this is the standard RuneLite dev-loop entry point.
 * Right-click this file in IntelliJ and choose "Run" (make sure the run
 * configuration's VM options include -ea) to boot the actual RuneLite
 * client with Bank Groups already loaded, so you can test against a live
 * bank.
 */
public class BankGroupsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BankGroupsPlugin.class);
		RuneLite.main(args);
	}
}

package com.bankgroups;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;

@PluginDescriptor(
		name = "Bank Groups",
		description = "Highlight bank items into up to 10 colour-coded, named groups (e.g. melee gear, mage gear, potions)",
		tags = {"bank", "highlight", "organization", "groups"}
)
public class BankGroupsPlugin extends Plugin
{
	static final String CONFIG_GROUP = "bankgroups";
	private static final String CONFIG_KEY_GROUPS = "groupdata";
	private static final int GROUP_COUNT = 10;

	// Reasonably distinct default palette for the 10 starter groups.
	private static final Color[] DEFAULT_COLORS = {
			new Color(230, 60, 60),   // red
			new Color(60, 140, 230),  // blue
			new Color(60, 200, 90),   // green
			new Color(230, 190, 40),  // yellow
			new Color(190, 90, 230),  // purple
			new Color(240, 140, 30),  // orange
			new Color(40, 210, 210),  // teal
			new Color(230, 100, 170), // pink
			new Color(150, 150, 150), // grey
			new Color(120, 200, 40)   // lime
	};

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private BankGroupsOverlay overlay;

	@Inject
	private BankGroupsConfig config;

	private BankGroupsPanel panel;
	private NavigationButton navButton;

	private final List<GroupData> groups = new ArrayList<>();
	private boolean editMode = false;
	private int activeGroupId = -1;

	@Provides
	BankGroupsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankGroupsConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadGroups();

		overlayManager.add(overlay);

		panel = new BankGroupsPanel(this);
		BufferedImage icon = createIcon();
		navButton = NavigationButton.builder()
				.tooltip("Bank Groups")
				.icon(icon)
				.priority(6)
				.panel(panel)
				.build();
		clientToolbar.addNavigation(navButton);
	}

	/**
	 * Draws a simple chest-with-dot icon in code, so the plugin doesn't
	 * depend on a bundled image resource that might not have made it into
	 * the build.
	 */
	private BufferedImage createIcon()
	{
		BufferedImage img = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

			g.setColor(new Color(120, 95, 55));
			g.fillRoundRect(1, 8, 22, 14, 4, 4);
			g.setColor(new Color(90, 70, 40));
			g.fillRoundRect(1, 3, 22, 8, 4, 4);

			g.setColor(new Color(20, 15, 10));
			g.drawRoundRect(1, 3, 21, 19, 4, 4);

			g.setColor(new Color(230, 60, 60));
			g.fillOval(9, 12, 6, 6);
		}
		finally
		{
			g.dispose();
		}
		return img;
	}

	@Override
	protected void shutDown()
	{
		saveGroups();
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		editMode = false;
		activeGroupId = -1;
	}

	// ---------------------------------------------------------------
	// Edit mode / bank click interception
	// ---------------------------------------------------------------

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// The RSProfile our saved data lives under doesn't exist until a
		// character is actually logged in - startUp() runs at client boot,
		// well before that, so the very first loadGroups() call always finds
		// nothing and falls back to fresh defaults. Reload here, once a
		// profile genuinely exists, to pick up whatever was actually saved.
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadGroups();
			if (panel != null)
			{
				panel.rebuild();
			}
		}
	}

	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		if (!editMode)
		{
			return;
		}

		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.isHidden())
		{
			return;
		}

		MenuEntry[] entries = client.getMenuEntries();
		if (entries.length == 0)
		{
			return;
		}

		// Strip out every default action on this widget - Withdraw-1/5/10/X/All,
		// Examine, Placeholder, everything. This is deliberately aggressive:
		// leaving even one original entry in place risks it triggering special
		// behaviour (e.g. the numeric quantity prompt "Withdraw-X" opens for
		// stackable items like coins) that our click handler can't cleanly
		// intercept. Nothing from the bank's own menu survives while editing.
		List<MenuEntry> kept = new ArrayList<>();
		MenuEntry sourceEntry = null;
		for (MenuEntry entry : entries)
		{
			if (entry.getParam1() == InterfaceID.Bankmain.ITEMS)
			{
				if (sourceEntry == null)
				{
					sourceEntry = entry;
				}
				continue;
			}
			kept.add(entry);
		}

		if (sourceEntry == null)
		{
			// Nothing on this widget - leave the rest of the menu untouched.
			return;
		}

		if (activeGroupId >= 0)
		{
			int itemId = resolveItemId(sourceEntry.getParam0(), sourceEntry.getParam1());
			GroupData active = getGroupById(activeGroupId);
			if (itemId > 0 && active != null)
			{
				int canonicalId = itemManager.canonicalize(itemId);
				String label = active.contains(canonicalId) ? "Remove from " : "Add to ";

				MenuEntry custom = client.createMenuEntry(-1)
						.setOption(label + active.getName())
						.setTarget(sourceEntry.getTarget())
						.setType(MenuAction.RUNELITE)
						.setParam0(sourceEntry.getParam0())
						.setParam1(sourceEntry.getParam1())
						.setIdentifier(sourceEntry.getIdentifier());
				kept.add(custom);
			}
		}

		client.setMenuEntries(kept.toArray(new MenuEntry[0]));
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!editMode)
		{
			return;
		}

		if (!isBankItemContainer(event.getParam1()))
		{
			return;
		}

		// Consume unconditionally: while in edit mode, nothing in the bank item
		// container should withdraw, examine-and-close, or otherwise act normally.
		event.consume();

		if (activeGroupId < 0)
		{
			return;
		}

		int itemId = resolveItemId(event.getParam0(), event.getParam1());
		if (itemId <= 0)
		{
			return;
		}

		int canonicalId = itemManager.canonicalize(itemId);
		toggleItemInActiveGroup(canonicalId);
	}

	private boolean isBankItemContainer(int widgetId)
	{
		return widgetId == InterfaceID.Bankmain.ITEMS;
	}

	/**
	 * Resolves the item ID under a bank-item menu action. actionParam0 /
	 * getParam0() is the dynamic child index within the bank item container
	 * for widget-sourced menu entries.
	 */
	private int resolveItemId(int childIndex, int widgetId)
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null)
		{
			return -1;
		}

		Widget[] children = container.getDynamicChildren();
		if (children == null || childIndex < 0 || childIndex >= children.length)
		{
			return -1;
		}

		Widget itemWidget = children[childIndex];
		return itemWidget == null ? -1 : itemWidget.getItemId();
	}

	// ---------------------------------------------------------------
	// Group management
	// ---------------------------------------------------------------

	private void toggleItemInActiveGroup(int canonicalId)
	{
		GroupData active = getGroupById(activeGroupId);
		if (active == null)
		{
			return;
		}

		// Groups are mutually exclusive: an item leaving another group before
		// joining this one, so borders never overlap.
		for (GroupData other : groups)
		{
			if (other.getId() != active.getId())
			{
				other.remove(canonicalId);
			}
		}

		active.toggle(canonicalId);
		saveGroups();

		if (panel != null)
		{
			panel.rebuild();
		}
	}

	/**
	 * @return the group (if any) that a canonical item ID belongs to.
	 */
	public GroupData getGroupForItem(int canonicalId)
	{
		for (GroupData group : groups)
		{
			if (group.contains(canonicalId))
			{
				return group;
			}
		}
		return null;
	}

	public GroupData getGroupById(int id)
	{
		for (GroupData group : groups)
		{
			if (group.getId() == id)
			{
				return group;
			}
		}
		return null;
	}

	public List<GroupData> getGroups()
	{
		return groups;
	}

	public boolean isEditMode()
	{
		return editMode;
	}

	public void setEditMode(boolean editMode)
	{
		this.editMode = editMode;
		if (!editMode)
		{
			activeGroupId = -1;
		}
	}

	public int getActiveGroupId()
	{
		return activeGroupId;
	}

	public void setActiveGroupId(int activeGroupId)
	{
		this.activeGroupId = activeGroupId;
	}

	// ---------------------------------------------------------------
	// Persistence (per RuneLite profile)
	// ---------------------------------------------------------------

	void saveGroups()
	{
		String json = gson.toJson(groups);
		configManager.setRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY_GROUPS, json);
	}

	private void loadGroups()
	{
		groups.clear();

		String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY_GROUPS);
		if (json != null)
		{
			Type type = new TypeToken<ArrayList<GroupData>>()
			{
			}.getType();
			List<GroupData> loaded = gson.fromJson(json, type);
			if (loaded != null && !loaded.isEmpty())
			{
				groups.addAll(loaded);
			}
		}

		if (groups.isEmpty())
		{
			for (int i = 0; i < GROUP_COUNT; i++)
			{
				groups.add(new GroupData(i, "Group " + (i + 1), DEFAULT_COLORS[i % DEFAULT_COLORS.length]));
			}
		}
	}
}

package com.bankgroups;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws a single merged outline per group across the whole bank grid, rather
 * than a box per item: adjacent same-group cells share an edge with no
 * border drawn between them, so a block of items reads as one Tetris-style
 * piece instead of many separate boxes.
 * <p>
 * Row/column position for each item is derived from its ABSOLUTE on-screen
 * position divided by the grid pitch (item spacing) - not by counting which
 * items happen to be present in a row. That distinction matters: if a row
 * has an empty slot in the middle, counting-based indexing silently
 * compresses everything after the gap and desyncs adjacency right at
 * irregular shapes. Position-based indexing doesn't have that problem.
 */
public class BankGroupsOverlay extends Overlay
{
	private final Client client;
	private final BankGroupsPlugin plugin;
	private final ItemManager itemManager;
	private final BankGroupsConfig config;

	@Inject
	private BankGroupsOverlay(Client client, BankGroupsPlugin plugin, ItemManager itemManager, BankGroupsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.itemManager = itemManager;
		this.config = config;
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.isHidden())
		{
			return null;
		}

		Widget[] children = container.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			return null;
		}

		List<RawItem> raw = new ArrayList<>();
		TreeSet<Integer> xs = new TreeSet<>();
		TreeSet<Integer> ys = new TreeSet<>();

		for (Widget child : children)
		{
			if (child == null || child.isHidden())
			{
				continue;
			}

			int itemId = child.getItemId();
			if (itemId <= 0)
			{
				continue;
			}

			Rectangle bounds = child.getBounds();
			if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
			{
				continue;
			}

			raw.add(new RawItem(bounds, itemId));
			xs.add(bounds.x);
			ys.add(bounds.y);
		}

		if (raw.isEmpty())
		{
			return null;
		}

		int pitchX = commonPitch(xs, raw.get(0).bounds.width);
		int pitchY = commonPitch(ys, raw.get(0).bounds.height);

		List<Cell> cells = new ArrayList<>();
		for (RawItem r : raw)
		{
			// Resolve placeholders to their real item so a group matches an
			// item whether it's physically present or just a placeholder.
			int canonicalId = itemManager.canonicalize(r.itemId);
			GroupData group = plugin.getGroupForItem(canonicalId);
			if (group == null)
			{
				continue;
			}

			// Grid position (for adjacency only, never for pixel placement)
			// from absolute pixel position, not from counting items present
			// in this row/column.
			int col = Math.round(r.bounds.x / (float) pitchX);
			int row = Math.round(r.bounds.y / (float) pitchY);

			// The drawn rectangle is anchored to THIS item's own real
			// on-screen position, not extrapolated from some other
			// reference item. Extrapolating from a single reference point
			// (an earlier version of this code did that) multiplies any
			// tiny pitch measurement error by how far a row is from the
			// reference - invisible near the top of the bank, but growing
			// steadily worse toward the bottom and while scrolling. Using
			// each item's own bounds directly has no such drift: it's
			// always anchored to where that item actually is.
			int rawX = r.bounds.x + config.horizontalOffset();
			int rawY = r.bounds.y - config.topClearance() + config.verticalOffset();
			int rawW = pitchX;
			int rawH = pitchY + config.topClearance();

			int pad = config.cellPadding();
			Rectangle tile = new Rectangle(rawX + pad, rawY + pad, rawW - pad * 2, rawH - pad * 2);

			cells.add(new Cell(tile, group, row, col));
		}

		if (cells.isEmpty())
		{
			return null;
		}

		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			// Clip to the bank's visible viewport so scrolled-off rows don't
			// paint outside the panel.
			Rectangle clip = container.getBounds();
			if (clip != null)
			{
				g.setClip(clip);
			}

			// Every shape here is an axis-aligned rectangle/line - antialiasing
			// only introduces sub-pixel blending seams at shared edges between
			// differently-coloured tiles, so it stays off.
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

			// Fill every cell first so the border strokes drawn afterwards
			// sit cleanly on top of the fill rather than under it.
			for (Cell cell : cells)
			{
				Color base = cell.group.getColor();
				g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), config.fillOpacity()));
				g.fill(cell.bounds);
			}

			g.setStroke(new BasicStroke(config.borderWidth()));

			for (Cell cell : cells)
			{
				g.setColor(cell.group.getColor());

				Rectangle b = cell.bounds;
				boolean hasTop = hasNeighbor(cells, cell, 0, -1);
				boolean hasBottom = hasNeighbor(cells, cell, 0, 1);
				boolean hasLeft = hasNeighbor(cells, cell, -1, 0);
				boolean hasRight = hasNeighbor(cells, cell, 1, 0);

				if (!hasTop)
				{
					g.drawLine(b.x, b.y, b.x + b.width, b.y);
				}
				if (!hasBottom)
				{
					g.drawLine(b.x, b.y + b.height, b.x + b.width, b.y + b.height);
				}
				if (!hasLeft)
				{
					g.drawLine(b.x, b.y, b.x, b.y + b.height);
				}
				if (!hasRight)
				{
					g.drawLine(b.x + b.width, b.y, b.x + b.width, b.y + b.height);
				}
			}
		}
		finally
		{
			g.dispose();
		}

		return null;
	}

	/**
	 * @return the most common positive gap between consecutive values in a
	 * sorted set of distinct pixel positions - i.e. the true single-cell
	 * spacing. Using the most common gap (rather than the smallest one) means
	 * a single anomalous pair anywhere on screen can't throw off the pitch
	 * for the entire bank.
	 */
	private int commonPitch(TreeSet<Integer> sortedDistinct, int fallback)
	{
		Map<Integer, Integer> frequency = new HashMap<>();
		Integer previous = null;
		for (int value : sortedDistinct)
		{
			if (previous != null)
			{
				int diff = value - previous;
				if (diff > 0)
				{
					frequency.merge(diff, 1, Integer::sum);
				}
			}
			previous = value;
		}

		int best = fallback;
		int bestCount = 0;
		for (Map.Entry<Integer, Integer> entry : frequency.entrySet())
		{
			if (entry.getValue() > bestCount)
			{
				bestCount = entry.getValue();
				best = entry.getKey();
			}
		}
		return best;
	}

	/**
	 * @param dx -1 = check the cell to the left, 1 = check the cell to the right, 0 = don't check horizontally
	 * @param dy -1 = check the cell above, 1 = check the cell below, 0 = don't check vertically
	 * @return true if another cell in the same group sits directly adjacent in that direction
	 */
	private boolean hasNeighbor(List<Cell> cells, Cell cell, int dx, int dy)
	{
		int targetRow = cell.row + dy;
		int targetCol = cell.col + dx;

		for (Cell other : cells)
		{
			if (other == cell || other.group.getId() != cell.group.getId())
			{
				continue;
			}

			if (other.row == targetRow && other.col == targetCol)
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * One item widget with its real screen bounds, not yet filtered by group
	 * membership or converted to grid coordinates.
	 */
	private static class RawItem
	{
		final Rectangle bounds;
		final int itemId;

		RawItem(Rectangle bounds, int itemId)
		{
			this.bounds = bounds;
			this.itemId = itemId;
		}
	}

	private static class Cell
	{
		final Rectangle bounds;
		final GroupData group;
		final int row;
		final int col;

		Cell(Rectangle bounds, GroupData group, int row, int col)
		{
			this.bounds = bounds;
			this.group = group;
			this.row = row;
			this.col = col;
		}
	}
}

package com.bankgroups;

import java.awt.Color;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * A single highlight group: a name, a colour, and the set of canonical
 * (placeholder-resolved) item IDs that belong to it.
 * <p>
 * Instances of this class are serialized to JSON via Gson and stored per
 * RuneLite profile through {@link BankGroupsPlugin}, so field names matter
 * for (de)serialization - don't rename them without a migration plan.
 */
public class GroupData
{
	private final int id;
	private String name;
	private int colorRgb;
	private final Set<Integer> itemIds = new LinkedHashSet<>();

	public GroupData(int id, String name, Color color)
	{
		this.id = id;
		this.name = name;
		this.colorRgb = color.getRGB();
	}

	public int getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	public void setName(String name)
	{
		this.name = name;
	}

	public Color getColor()
	{
		return new Color(colorRgb, true);
	}

	public void setColor(Color color)
	{
		this.colorRgb = color.getRGB();
	}

	public Set<Integer> getItemIds()
	{
		return itemIds;
	}

	public boolean contains(int canonicalItemId)
	{
		return itemIds.contains(canonicalItemId);
	}

	/**
	 * @return true if the item was added, false if it was removed (it was already present)
	 */
	public boolean toggle(int canonicalItemId)
	{
		if (itemIds.remove(canonicalItemId))
		{
			return false;
		}
		itemIds.add(canonicalItemId);
		return true;
	}

	public void remove(int canonicalItemId)
	{
		itemIds.remove(canonicalItemId);
	}
}

package com.bankgroups;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

/**
 * Visual tuning knobs. The actual group definitions (names/colours/item
 * membership) are NOT exposed here - they're managed from the side panel
 * and persisted separately per-profile, since they're a dynamic list rather
 * than fixed settings.
 */
@ConfigGroup(BankGroupsPlugin.CONFIG_GROUP)
public interface BankGroupsConfig extends Config
{
	@Range(min = 0, max = 255)
	@ConfigItem(
			keyName = "fillOpacity",
			name = "Fill opacity",
			description = "Transparency of the highlight fill inside the border (0 = invisible, 255 = solid)",
			position = 0
	)
	default int fillOpacity()
	{
		return 36;
	}

	@Range(min = 1, max = 4)
	@ConfigItem(
			keyName = "borderWidth",
			name = "Border width",
			description = "Thickness in pixels of the group border outline",
			position = 1
	)
	default int borderWidth()
	{
		return 2;
	}

	@Range(min = -15, max = 15)
	@ConfigItem(
			keyName = "horizontalOffset",
			name = "Horizontal offset",
			description = "Shifts the highlight left (negative) or right (positive) to center it between items",
